mapper.select:
select 
from review_git_credential c
where c.credential_id = #{credentialId}

select credential_id, credential_name, provider, auth_type, token_ciphertext, status
from review_git_credential
where credential_id = #{credentialId}

select 
from review_git_credential c
where 1 = 1

    and c.credential_name like concat('%', #{credentialName}, '%')


    and c.provider = #{provider}


    and c.auth_type = #{authType}


    and c.status = #{status}


    and c.last_check_status = #{lastCheckStatus}

order by c.credential_id desc

select credential_id, credential_name, provider
from review_git_credential
where provider = #{provider}
  and credential_name = #{credentialName}

  and credential_id != #{excludeCredentialId}

limit 1

mapper.update:
update review_git_credential
credential_name = #{credentialName}, token_ciphertext = #{tokenCiphertext}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where credential_id = #{credentialId}

update review_git_credential
set last_check_status = 'UNTESTED', last_check_message = null, last_check_time = null
where credential_id = #{credentialId}
